339	-- ---------------------------------------------------------------------------------------------
340	-- reject_payment (R24)
341	-- ---------------------------------------------------------------------------------------------
342	create or replace function private.reject_payment(p_actor_id uuid, p_payment_id uuid, p_reason text)
343	returns table(status text)
344	language plpgsql
345	security invoker
346	set search_path = ''
347	as $$
348	#variable_conflict use_column
349	declare
350	  v_pay public.payments;
351	begin
352	  -- Error contract order: not found (404) before validation (400) before state (409).
353	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
354	
355	  if p_reason is null or length(btrim(p_reason)) < 5 then
356	    raise exception using errcode = 'P0400', message = 'Reason must be at least 5 characters';
357	  end if;
358	  if v_pay.status <> 'pending_verification' then
359	    raise exception using errcode = 'P0409', message = 'Payment is not pending';
360	  end if;
361	
362	  update public.payments p
363	     set status = 'rejected', reason = btrim(p_reason), decided_by = p_actor_id, decided_at = now()
364	   where p.id = p_payment_id;
365	
366	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
367	  values (v_pay.org_id, p_actor_id, 'payment.rejected', p_payment_id,
368	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
369	                             'reason', btrim(p_reason)));
370	
371	  return query select 'rejected'::text;
372	end;
373	$$;
374	
375	-- ---------------------------------------------------------------------------------------------
376	-- void_payment (R24, D14): removes only this payment's allocations; other payments untouched.
377	-- ---------------------------------------------------------------------------------------------
378	create or replace function private.void_payment(p_actor_id uuid, p_payment_id uuid, p_reason text)
379	returns table(status text)
380	language plpgsql
381	security invoker
382	set search_path = ''
383	as $$
384	#variable_conflict use_column
385	declare
386	  v_pay public.payments;
387	  v_released bigint;
388	begin
389	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
390	
391	  if p_reason is null or length(btrim(p_reason)) < 5 then
392	    raise exception using errcode = 'P0400', message = 'Reason must be at least 5 characters';
393	  end if;
394	  if v_pay.status <> 'approved' then
395	    raise exception using errcode = 'P0409', message = 'Payment is not approved';
396	  end if;
397	
398	  with d as (
399	    delete from public.payment_allocations a where a.payment_id = p_payment_id returning a.amount_sen
400	  )
401	  select coalesce(sum(d.amount_sen), 0) into v_released from d;
402	
403	  -- D14: unapplied_sen of other payments is NOT re-applied to the reopened invoices.
404	  -- decided_by/decided_at keep the approver; the voider is recorded in audit_log.
405	  update public.payments p
406	     set status = 'voided', reason = btrim(p_reason)
407	   where p.id = p_payment_id;
408	
409	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
410	  values (v_pay.org_id, p_actor_id, 'payment.voided', p_payment_id,
411	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
412	                             'released_sen', v_released, 'reason', btrim(p_reason)));
413	
414	  return query select 'voided'::text;
415	end;
416	$$;
