22	// R31: strictly read-only. Only the gateway webhook settles a bill, so the `paid` query parameter is never
23	// read here; the status shown is whatever the database says.
24	export default async function PaymentReturnPage({
25	  searchParams,
26	}: {
27	  searchParams: Promise<{ bill_id?: string | string[] }>;
28	}) {
29	  const { bill_id } = await searchParams;
30	  const billId = Array.isArray(bill_id) ? bill_id[0] : bill_id;
31	
32	  const supabase = await createClient();
33	  const { data, error } = await supabase.auth.getUser();
34	  if (error || !data.user) {
35	    // Send the tenant back here after signing in; the login form only follows same-origin paths.
36	    const back = `/payments/return${billId ? `?bill_id=${encodeURIComponent(billId)}` : ""}`;
37	    redirect(`/login?next=${encodeURIComponent(back)}`);
38	  }
39	
40	  let bill: GatewayBillDto | null = null;
41	  if (billId) {
42	    try {
43	      bill = await getGatewayBill({ userId: data.user.id }, billId);
44	    } catch (e) {
45	      // Unknown, malformed or someone else's bill all look the same (R38); anything else is a real error.
46	      if (!(e instanceof ApiError && e.status === 404)) throw e;
47	    }
48	  }
49	
50	  return (
51	    <Card className="max-w-lg">
52	      <CardHeader>
53	        <CardTitle>Payment status</CardTitle>
54	        {bill && <CardDescription>The status below is read from our records.</CardDescription>}
55	      </CardHeader>
56	      <CardContent className="flex flex-col gap-4">
57	        {bill ? (
58	          <>
59	            <div className="flex items-center gap-2">
60	              <Badge variant={bill.status === "paid" ? "default" : bill.status === "failed" ? "destructive" : "secondary"}>
61	                {bill.status === "paid" ? "Paid" : bill.status === "failed" ? "Failed" : "Pending"}
62	              </Badge>
63	              <p className="text-sm" data-testid="bill-status-message">
64	                {MESSAGE[bill.status]}
65	              </p>
66	            </div>
67	            <dl className="grid grid-cols-[max-content_1fr] gap-x-4 gap-y-1 text-sm">
68	              <dt className="text-muted-foreground">Bill id</dt>
69	              <dd className="font-mono break-all">{bill.billId}</dd>
70	              <dt className="text-muted-foreground">Amount</dt>
71	              <dd>{formatSen(bill.amountSen)}</dd>
72	            </dl>
73	          </>
74	        ) : (
75	          <p className="text-sm" data-testid="bill-status-message">
76	            Bill not found
77	          </p>
78	        )}
79	        <div className="flex flex-wrap gap-2">
80	          {bill?.status === "pending" && <RefreshButton />}
81	          <Link href="/tenant" className={cn(buttonVariants({ variant: "outline" }))}>
82	            Back to my tenancy
83	          </Link>
84	        </div>
