25	import { loadCaller } from "@/server/access";
26	import { collectionsReport, overdueCount } from "@/server/services/reports";
27	
28	const REPORT_MONTHS = 6;
29	
30	// "YYYY-MM" shifted by a whole number of months; integer month math, no Date (R3/R52).
31	function shiftMonth(ym: string, delta: number): string {
32	  const index = Number(ym.slice(0, 4)) * 12 + (Number(ym.slice(5, 7)) - 1) + delta;
33	  const y = Math.floor(index / 12);
34	  const m = (index % 12) + 1;
35	  return `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}`;
36	}
37	
38	export default async function DashboardPage() {
39	  const userId = await getUserId();
40	  if (!userId) redirect("/login");
41	
42	  const caller = await loadCaller(userId);
43	  // UX redirect only: the services re-check the role themselves (R36).
44	  if (!caller.member) {
45	    if (caller.tenantIds.length > 0) redirect("/tenant");
46	    return (
47	      <Card className="max-w-md">
48	        <CardHeader>
49	          <CardTitle>No access</CardTitle>
50	          <CardDescription>This account is not linked to an organisation.</CardDescription>
51	        </CardHeader>
52	      </Card>
53	    );
54	  }
55	
56	  return (
57	    <>
58	      <h1 className="mb-6 text-2xl font-semibold tracking-tight">Dashboard</h1>
59	      <Suspense fallback={<DashboardSkeleton />}>
60	        <DashboardBody userId={userId} />
61	      </Suspense>
62	    </>
63	  );
64	}
65	
66	async function DashboardBody({ userId }: { userId: string }) {
67	  const ctx = { userId };
68	  const now = new Date();
69	  // The current month is the Malaysia calendar month of "now", then five months back.
70	  const currentMonth = toMytDate(now).slice(0, 7);
71	  const [overdue, report] = await Promise.all([
72	    overdueCount(ctx, now),
73	    collectionsReport(ctx, shiftMonth(currentMonth, -(REPORT_MONTHS - 1)), currentMonth),
74	  ]);
75	
76	  const total = report.reduce((sum, r) => sum + r.collectedSen, 0);
77	  const max = report.reduce((m, r) => Math.max(m, r.collectedSen), 0);
78	
79	  return (
80	    <>
81	      <div className="grid gap-4 sm:grid-cols-2">
82	        <Card>
83	          <CardHeader>
84	            <CardDescription>Overdue invoices</CardDescription>
85	            <CardTitle className="text-3xl tabular-nums" data-testid="overdue-count">
86	              <Link href="/leases" className="underline-offset-4 hover:underline" aria-label={`${overdue} overdue invoices, view leases`}>
87	                {overdue}
88	              </Link>
89	            </CardTitle>
90	          </CardHeader>
91	          <CardContent className="text-sm text-muted-foreground">
92	            {overdue === 0
93	              ? "Nothing is overdue. Every invoice past its due date is paid."
94	              : "Invoices past their due date (Malaysia time) that are not fully paid."}
95	          </CardContent>
96	        </Card>
97	        <Card>
98	          <CardHeader>
99	            <CardDescription>Collected, last {REPORT_MONTHS} months</CardDescription>
100	            <CardTitle className="text-3xl tabular-nums">{formatSen(total)}</CardTitle>
101	          </CardHeader>
102	          <CardContent className="text-sm text-muted-foreground">
103	            Approved payments, by the month they were received.
104	          </CardContent>
105	        </Card>
106	      </div>
107	
108	      <Card className="mt-6">
109	        <CardHeader>
110	          <CardTitle>Collections by month</CardTitle>
111	          <CardDescription>
112	            {monthLabel(report[0]?.month ?? currentMonth)} to {monthLabel(currentMonth)}, approved payments only.
113	          </CardDescription>
114	        </CardHeader>
115	        <CardContent>
116	          {total === 0 ? (
117	            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
118	              No approved payments in these months yet. Record a payment on a lease to see it here.
119	            </p>
120	          ) : null}
121	          <Table className={total === 0 ? "mt-4" : undefined}>
122	            <TableHeader>
123	              <TableRow>
124	                <TableHead>Month</TableHead>
125	                <TableHead className="w-1/2">Collected</TableHead>
126	                <TableHead className="text-right">Amount</TableHead>
127	              </TableRow>
128	            </TableHeader>
129	            <TableBody>
130	              {report.map((r) => (
131	                <TableRow key={r.month}>
132	                  <TableCell className="font-medium">
133	                    {monthLabel(r.month)}
134	                    {r.month === currentMonth && (
135	                      <Badge variant="outline" className="ml-2">
136	                        This month
137	                      </Badge>
138	                    )}
139	                  </TableCell>
140	                  <TableCell>
141	                    <div className="h-2 w-full rounded-full bg-muted" aria-hidden="true">
142	                      <div
143	                        className="h-2 rounded-full bg-primary"
144	                        style={{ width: max === 0 ? "0%" : `${Math.round((r.collectedSen / max) * 100)}%` }}
145	                      />
146	                    </div>
147	                  </TableCell>
148	                  <TableCell className="text-right tabular-nums">{formatSen(r.collectedSen)}</TableCell>
149	                </TableRow>
150	              ))}
151	            </TableBody>
152	          </Table>
153	        </CardContent>
154	      </Card>
155	    </>
156	  );
157	}
